// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AcceptApplication O dono aceita a candidatura
	// (POST /applications/{id}/accept)
	AcceptApplication(ctx context.Context, request AcceptApplicationRequestObject) (AcceptApplicationResponseObject, error)
	// RejectApplication O dono recusa a candidatura
	// (POST /applications/{id}/reject)
	RejectApplication(ctx context.Context, request RejectApplicationRequestObject) (RejectApplicationResponseObject, error)
	// WithdrawApplication O candidato retira a candidatura pendente
	// (POST /applications/{id}/withdraw)
	WithdrawApplication(ctx context.Context, request WithdrawApplicationRequestObject) (WithdrawApplicationResponseObject, error)
	// CreateSessionFromDiscord Troca o código do Discord por uma sessão
	// (POST /auth/discord)
	CreateSessionFromDiscord(ctx context.Context, request CreateSessionFromDiscordRequestObject) (CreateSessionFromDiscordResponseObject, error)
	// ListCharacters Personagens do Usuário da sessão
	// (GET /characters)
	ListCharacters(ctx context.Context, request ListCharactersRequestObject) (ListCharactersResponseObject, error)
	// CreateCharacter Cadastra um personagem
	// (POST /characters)
	CreateCharacter(ctx context.Context, request CreateCharacterRequestObject) (CreateCharacterResponseObject, error)
	// DeleteCharacter Exclui um personagem
	// (DELETE /characters/{id})
	DeleteCharacter(ctx context.Context, request DeleteCharacterRequestObject) (DeleteCharacterResponseObject, error)
	// UpdateCharacter Edita um personagem
	// (PUT /characters/{id})
	UpdateCharacter(ctx context.Context, request UpdateCharacterRequestObject) (UpdateCharacterResponseObject, error)
	// SetMainCharacter Torna o personagem o principal
	// (PUT /characters/{id}/main)
	SetMainCharacter(ctx context.Context, request SetMainCharacterRequestObject) (SetMainCharacterResponseObject, error)
	// ListClasses Catálogo de classes
	// (GET /classes)
	ListClasses(ctx context.Context, request ListClassesRequestObject) (ListClassesResponseObject, error)
	// GetHealthz Estado da API e do banco
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// ListInstances Catálogo de instâncias
	// (GET /instances)
	ListInstances(ctx context.Context, request ListInstancesRequestObject) (ListInstancesResponseObject, error)
	// ListLobbies Lobbies abertos num intervalo de dias
	// (GET /lobbies)
	ListLobbies(ctx context.Context, request ListLobbiesRequestObject) (ListLobbiesResponseObject, error)
	// CreateLobby Cria um lobby
	// (POST /lobbies)
	CreateLobby(ctx context.Context, request CreateLobbyRequestObject) (CreateLobbyResponseObject, error)
	// GetLobby Detalhe do lobby
	// (GET /lobbies/{id})
	GetLobby(ctx context.Context, request GetLobbyRequestObject) (GetLobbyResponseObject, error)
	// UpdateLobby Edita o lobby
	// (PUT /lobbies/{id})
	UpdateLobby(ctx context.Context, request UpdateLobbyRequestObject) (UpdateLobbyResponseObject, error)
	// ApplyToLobby Candidata-se ao lobby
	// (POST /lobbies/{id}/applications)
	ApplyToLobby(ctx context.Context, request ApplyToLobbyRequestObject) (ApplyToLobbyResponseObject, error)
	// CancelLobby Cancela o lobby
	// (POST /lobbies/{id}/cancel)
	CancelLobby(ctx context.Context, request CancelLobbyRequestObject) (CancelLobbyResponseObject, error)
	// GetMe Usuário da sessão
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListMyApplications Minhas candidaturas
	// (GET /me/applications)
	ListMyApplications(ctx context.Context, request ListMyApplicationsRequestObject) (ListMyApplicationsResponseObject, error)
	// DeleteSession Encerra a sessão atual
	// (DELETE /session)
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

